waitTime = data["ELEMENT"]["wait_time"]
downloadpath = os.path.abspath(data["AUTO_SITE"]["download_path"])
browser = data["AUTO_SITE"]["browser"]
emsURL = data["EMS"]["url"]
emsUsr = data["EMS"]["login_username"]
emsPwd = data["EMS"]["login_password"]
pmList = data["PM"]
pmCount = len(data["PM"])

class TestMax():
    def setup_method(self):
        match browser:
            case "chrome":
                options = webdriver.ChromeOptions()
                options.add_argument('ignore-certificate-errors')
                prefs = {
                    "download.default_directory": downloadpath,
                    "download.prompt_for_download": False,
                    "download.directory_upgrade": True
                }
                options.add_experimental_option("prefs", prefs)
                self.driver = webdriver.Chrome(options)
            case "edge":
                options = webdriver.EdgeOptions()
                options.add_argument('ignore-certificate-errors')
                prefs = {
                    "download.default_directory": downloadpath,
                    "download.prompt_for_download": False,
                    "download.directory_upgrade": True
                }
                options.add_experimental_option("prefs", prefs)
                self.driver = webdriver.Edge(options)
            case "firefox":
                options = webdriver.FirefoxOptions()
                options.add_argument('-ignore-certificate-errors')
                options.set_preference("browser.download.folderList", 2)
                options.set_preference("browser.download.dir", downloadpath)
                self.driver = webdriver.Firefox(options)
        self.driver.implicitly_wait(waitTime)
        self.vars = {}
        self.driver.get(emsURL)
        self.driver.maximize_window()
        loginEMS (self, emsUsr,emsPwd)
        WebDriverWait(self.driver, 180).until(EC.visibility_of_element_located((By.ID,"index_t_userName")))

    def teardown_method(self):
        self.driver.quit()

    def test_maxPm(self):
        deleteAllPm (self, "Current")
        deleteAllPm (self, "History")
        for pm in pmList:
            createPm (self, data["PM"][pm]["page"], data["PM"][pm]["pmtype"], data["PM"][pm]["ip"], data["PM"][pm]["interface"])